377	        const std::string call_id = item.value("call_id", "");
378	        ToolRequest request{item.value("name", ""), item.value("arguments", "{}")};
379	        const ToolDefinition* definition = ToolRegistry::instance().find(request.tool);
380	        const bool available = !m_title_request && definition != nullptr && available_in_app(*definition, m_allow_import, m_session.tool_names);
381	        ToolValidationResult validation;
382	        if (available)
383	            validation = ToolRegistry::instance().validate_call(*definition, request.arguments_json);
384	        // A call to no tool of this turn, or with arguments that miss the
385	        // tool's contract, never reaches a card. The model gets the refusal as
386	        // that call's result and may correct it, a bounded number of times
387	        // per turn.
388	        constexpr unsigned kRejectedCallLimit = 2;
389	        if ((!available || !validation.valid()) && m_config.refusal_listener)
390	            m_config.refusal_listener(request.tool, request.arguments_json, available ? validation.error->code : "unknown_tool");
391	        if (!call_id.empty() && !m_title_request && (!available || !validation.valid()) &&
392	            m_rejected_calls < kRejectedCallLimit) {
393	            ++m_rejected_calls;
394	            json error = available ?
395	                json{{"code", validation.error->code},
396	                     {"message", validation.error->message +
397	                                     " Nothing was queued. Check the arguments against this tool's parameters and call it again."}} :
398	                json{{"code", "unknown_tool"},
399	                     {"message", "There is no tool named \"" + request.tool + "\" here. Nothing was queued. Use one of the listed tools."}};
400	            json refusal{{"state", "failed"}, {"error", std::move(error)}};
401	            json input = m_input_history;
402	            input.push_back(json{{"type", "function_call_output"}, {"call_id", call_id}, {"output", refusal.dump()}});
403	            if (!post(std::move(input)))
404	                fail(AgentError{"agent_continuation_failed", "The Agent could not be told its tool arguments were invalid.", true});
405	            return;
406	        }
407	        if (call_id.empty() || !available || !validation.valid()) {
408	            fail(AgentError{"malformed_tool_call", "The Agent returned an invalid tool call.", false});
409	            return;
410	        }
411	        request.arguments_json = std::move(validation.arguments_json);
412	        m_pending_call_id = call_id;
413	        m_waiting_for_tool = true;
414	        AgentToolCall call{call_id, std::move(request), true};
415	        m_events.push_back(AgentEvent::tool_call(std::move(call)));
416	        return;
417	    }
418	    m_busy = false;
419	    m_events.push_back(AgentEvent::completed());
420	}
