422	void OpenAIResponsesAgent::parse_available()
423	{
424	    std::deque<QueuedHttpEvent> incoming;
425	    {
426	        std::lock_guard<std::mutex> lock(m_mutex);
427	        incoming.swap(m_http_events);
428	    }
429	    for (QueuedHttpEvent& queued : incoming) {
430	        if (queued.generation != m_http_generation)
431	            continue;
432	        AgentHttpEvent& event = queued.event;
433	        if (event.kind == AgentHttpEvent::Kind::Data) {
434	            m_sse_buffer += event.data;
435	            for (;;) {
436	                const std::size_t lf_pos = m_sse_buffer.find("\n\n");
437	                const std::size_t crlf_pos = m_sse_buffer.find("\r\n\r\n");
438	                const bool crlf_first = crlf_pos != std::string::npos &&
439	                                        (lf_pos == std::string::npos || crlf_pos < lf_pos);
440	                const std::size_t pos = crlf_first ? crlf_pos : lf_pos;
441	                if (pos == std::string::npos)
442	                    break;
443	                const std::string frame = m_sse_buffer.substr(0, pos);
444	                m_sse_buffer.erase(0, pos + (crlf_first ? 4 : 2));
445	                parse_sse_frame(frame);
446	            }
447	        } else if (event.kind == AgentHttpEvent::Kind::Error) {
448	            fail(http_error(event.status, event.error));
449	        } else if (!m_terminal_seen) {
450	            // A valid SSE stream may close immediately after its final data
451	            // line without a trailing blank-line delimiter. Consume that
452	            // complete residual frame before classifying the response.
453	            if (!m_sse_buffer.empty()) {
454	                parse_sse_frame(m_sse_buffer);
455	                m_sse_buffer.clear();
456	            }
457	            if (!m_terminal_seen)
458	                fail(AgentError{"malformed_response", "The Agent service ended before a complete response arrived.", true});
459	        }
460	    }
461	}
